 for a,b in {'at855':'at 855','tag818':'tag 818','855West12thAvenue':'855 West 12th Avenue','JimPattison':'Jim Pattison','818West10thAvenue':'818 West 10th Avenue','at2785AshStreet':'at 2785 Ash Street','VGHcampus':'VGH campus','confirm2775LaurelStreet':'confirm 2775 Laurel Street','at805West12thAvenue':'at 805 West 12th Avenue','at2255WesbrookMall':'at 2255 Wesbrook Mall','at2221WesbrookMall':'at 2221 Wesbrook Mall','confirm5HospitalRoad':'confirm 5 Hospital Road','provinceYT':'province YT','BCfilename':'BC filename','confirm7801ArgyleStreet':'confirm 7801 Argyle Street','West12thAvenue':'West 12th Avenue','existing11100-13thStreet':'existing 11100-13th Street'}.items():t=t.replace(a,b)
 return t
